            if all(row[c] == row[c - period]
                   for c in range(start + period, w)):
                # Need the repeated section to include the signal color.
                if signal not in row[start:]:
                    continue
                for c in range(w - period, w):
                    # Only extend into the background cells following the
                    # final observed signal, using the repeated motif.
                    pass
                # Extend the motif beyond the right edge as far as the grid
                # allows, changing predicted signal cells to 1.
                for c in range(w, w + period):
                    if row[c - period] == signal:
                        # No cells beyond the grid to paint; handled below
                        pass
                # In these tasks, incomplete repetitions occur at the right
                # edge: infer their next positions from the motif.
                # Find the start of the terminal repeated sequence.
